// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        // Add the reward token once
        c.addReward(rewardToken);
        // Try to add the same token again; should revert in reference but not in buggy version
        bool reverted = false;
        try c.addReward(rewardToken) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted, "addReward should revert when adding an existing reward token");
    }
}

